-- The journal schema. A journal is created from this file and must match it
-- exactly: `validate_schema` compares SQLite's stored DDL against a reference
-- built from it. There is one schema and no migration. A journal written by a
-- build with another schema or other hash definitions is never edited: `pull`
-- builds a new one from the phone, carrying forward what the old one knew
-- (`journal/carry.rs` reads it by the columns of `binding_records`,
-- `binding_versions`, `active_bindings`, `binding_sources`,
-- `binding_conversions`, `insert_conversions`, `insert_targets`,
-- `reservations` and `removal_targets`, which later schemas keep).
CREATE TABLE scope(singleton INTEGER PRIMARY KEY CHECK(singleton=1), device BLOB NOT NULL CHECK(length(device)=32), library BLOB NOT NULL CHECK(length(library)=32), nonce BLOB NOT NULL CHECK(length(nonce)=32)) STRICT;
CREATE TABLE attempts(id INTEGER PRIMARY KEY AUTOINCREMENT, kind INTEGER NOT NULL CHECK(kind IN (1,2)), state INTEGER NOT NULL CHECK(state IN (0,1,2,3,4,5,6)), content BLOB NOT NULL CHECK(length(content)<=512), operation BLOB NOT NULL CHECK(length(operation) BETWEEN 1 AND 4194304), operation_sha BLOB NOT NULL CHECK(length(operation_sha)=32), album BLOB CHECK(length(album)=8), artist BLOB CHECK(length(artist)=8), binding_id INTEGER, binding_version INTEGER, base_anchor INTEGER NOT NULL CHECK(base_anchor BETWEEN 0 AND 4294967294), input_receipt BLOB NOT NULL CHECK(length(input_receipt)=32), ready_receipt BLOB CHECK(length(ready_receipt)=32), signature BLOB CHECK(length(signature)=21), verified_receipt BLOB CHECK(length(verified_receipt)=32), verified_anchor INTEGER CHECK(verified_anchor BETWEEN 0 AND 4294967295), CHECK((state IN (0,3) AND ready_receipt IS NULL AND signature IS NULL AND verified_receipt IS NULL AND verified_anchor IS NULL) OR (state IN (1,4) AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND verified_receipt IS NULL AND verified_anchor IS NULL) OR (state=2 AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND verified_receipt IS NOT NULL AND verified_anchor IS NOT NULL) OR (state=5 AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND verified_receipt IS NOT NULL AND verified_anchor IS NULL) OR (state=6 AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND verified_receipt IS NOT NULL AND verified_anchor IS NOT NULL)), FOREIGN KEY(binding_id,binding_version) REFERENCES binding_versions(binding_id,version), CHECK((binding_id IS NULL)=(binding_version IS NULL)), CHECK(kind!=1 OR binding_id IS NULL), CHECK(kind!=2 OR binding_id IS NOT NULL), CHECK(state!=4 OR kind=1), CHECK(state!=6 OR kind=2)) STRICT;
CREATE UNIQUE INDEX one_outstanding ON attempts((1)) WHERE state IN (0,1);
CREATE TABLE active_bindings(audio BLOB PRIMARY KEY CHECK(length(audio)=32), binding_id INTEGER NOT NULL UNIQUE, version INTEGER NOT NULL, FOREIGN KEY(binding_id,audio) REFERENCES binding_records(id,audio), FOREIGN KEY(binding_id,version) REFERENCES binding_versions(binding_id,version)) STRICT;
CREATE VIEW bindings AS SELECT r.audio,r.track,r.path,v.content,v.receipt,v.anchor,v.receipt_kind FROM active_bindings a JOIN binding_records r ON r.id=a.binding_id AND r.audio=a.audio JOIN binding_versions v ON v.binding_id=a.binding_id AND v.version=a.version;
CREATE TRIGGER immutable_preparation BEFORE UPDATE OF kind,binding_id,binding_version,content,operation,operation_sha,album,artist,base_anchor,input_receipt ON attempts BEGIN SELECT RAISE(ABORT,'prepared evidence is immutable'); END;
CREATE TRIGGER forward_state BEFORE UPDATE OF state ON attempts WHEN NOT ((OLD.state=0 AND NEW.state IN (1,3)) OR (OLD.state=1 AND NEW.state IN (2,4,5,6))) BEGIN SELECT RAISE(ABORT,'invalid journal transition'); END;
CREATE TRIGGER active_not_retired BEFORE INSERT ON active_bindings WHEN EXISTS(SELECT 1 FROM binding_tombstones WHERE binding_id=NEW.binding_id) BEGIN SELECT RAISE(ABORT,'binding is retired'); END;
CREATE TRIGGER active_forward BEFORE UPDATE ON active_bindings WHEN NEW.audio!=OLD.audio OR NEW.binding_id!=OLD.binding_id OR NEW.version!=OLD.version+1 BEGIN SELECT RAISE(ABORT,'invalid active version transition'); END;
CREATE TRIGGER active_retirement BEFORE DELETE ON active_bindings WHEN NOT EXISTS(SELECT 1 FROM binding_tombstones WHERE binding_id=OLD.binding_id AND binding_version=OLD.version) BEGIN SELECT RAISE(ABORT,'verified deletion required'); END;
CREATE TABLE coordinations(id INTEGER PRIMARY KEY AUTOINCREMENT, kind INTEGER NOT NULL CHECK(kind IN(1,2,3)), state INTEGER NOT NULL CHECK(state IN(0,1)), phase INTEGER NOT NULL CHECK(phase BETWEEN 0 AND 255), revision INTEGER NOT NULL CHECK(revision>=0), intent BLOB NOT NULL CHECK(length(intent) BETWEEN 2 AND 16777216), intent_sha BLOB NOT NULL CHECK(length(intent_sha)=32), evidence TEXT NOT NULL CHECK(length(evidence) BETWEEN 2 AND 4096 AND substr(evidence,1,1)='/'), base_anchor INTEGER NOT NULL CHECK(base_anchor BETWEEN 0 AND 4294967295), outcome BLOB CHECK(outcome IS NULL OR length(outcome) BETWEEN 2 AND 1048576), CHECK((state=0)=(outcome IS NULL))) STRICT;
CREATE UNIQUE INDEX one_active_coordination ON coordinations((1)) WHERE state=0;
CREATE TRIGGER coordination_start BEFORE INSERT ON coordinations WHEN NEW.state!=0 OR NEW.revision!=0 OR NEW.phase!=0 BEGIN SELECT RAISE(ABORT,'a coordination starts Active at revision 0 and phase 0'); END;
CREATE TRIGGER coordination_immutable BEFORE UPDATE OF id,kind,intent,intent_sha,evidence,base_anchor ON coordinations BEGIN SELECT RAISE(ABORT,'coordination intent is immutable'); END;
CREATE TRIGGER coordination_revision BEFORE UPDATE ON coordinations WHEN NEW.revision!=OLD.revision+1 BEGIN SELECT RAISE(ABORT,'coordination revision must advance by one'); END;
CREATE TRIGGER coordination_terminal BEFORE UPDATE ON coordinations WHEN OLD.state!=0 BEGIN SELECT RAISE(ABORT,'coordination outcome is immutable'); END;
CREATE TRIGGER coordination_phase BEFORE UPDATE ON coordinations WHEN NEW.phase<OLD.phase BEGIN SELECT RAISE(ABORT,'coordination phase cannot move backwards'); END;
CREATE TRIGGER coordination_retained BEFORE DELETE ON coordinations BEGIN SELECT RAISE(ABORT,'coordination history is retained'); END;
CREATE TRIGGER attempt_batch_outstanding BEFORE INSERT ON attempts WHEN EXISTS(SELECT 1 FROM removal_batches WHERE state IN(0,1)) BEGIN SELECT RAISE(ABORT,'an outstanding removal batch requires settlement'); END;
CREATE TABLE removal_targets(batch INTEGER NOT NULL REFERENCES removal_batches(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), track BLOB NOT NULL CHECK(length(track)=8), item_pid INTEGER NOT NULL CHECK(item_pid!=0), path TEXT CHECK(path IS NULL OR length(path) BETWEEN 1 AND 4096), file_bytes INTEGER CHECK(file_bytes IS NULL OR file_bytes BETWEEN 1 AND 536870912), file_sha BLOB CHECK(file_sha IS NULL OR length(file_sha)=32), binding_id INTEGER, binding_version INTEGER, PRIMARY KEY(batch,ordinal), UNIQUE(batch,track), FOREIGN KEY(binding_id,binding_version) REFERENCES binding_versions(binding_id,version), CHECK((binding_id IS NULL)=(binding_version IS NULL)), CHECK((path IS NULL)=(file_bytes IS NULL) AND (path IS NULL)=(file_sha IS NULL))) STRICT;
CREATE TRIGGER removal_target_next BEFORE INSERT ON removal_targets WHEN NOT EXISTS(SELECT 1 FROM removal_batches WHERE id=NEW.batch AND state=0) OR NEW.ordinal!=(SELECT count(*) FROM removal_targets WHERE batch=NEW.batch) OR (NEW.binding_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM active_bindings WHERE binding_id=NEW.binding_id AND version=NEW.binding_version)) BEGIN SELECT RAISE(ABORT,'a removal target extends a Prepared batch in order and names an active binding version'); END;
CREATE TRIGGER removal_target_compensation BEFORE INSERT ON removal_targets WHEN EXISTS(SELECT 1 FROM removal_batches WHERE id=NEW.batch AND compensates IS NOT NULL) AND (NEW.ordinal!=0 OR NEW.path IS NOT NULL OR NEW.binding_id IS NOT NULL) BEGIN SELECT RAISE(ABORT,'a compensating batch removes exactly one locationless unowned row'); END;
CREATE TRIGGER removal_target_immutable BEFORE UPDATE ON removal_targets BEGIN SELECT RAISE(ABORT,'removal targets are immutable'); END;
CREATE TRIGGER removal_target_retained BEFORE DELETE ON removal_targets BEGIN SELECT RAISE(ABORT,'removal target history is retained'); END;
CREATE VIEW binding_tombstones AS SELECT t.binding_id,t.binding_version,b.id AS batch,b.result_receipt AS verified_receipt,b.verified_anchor FROM removal_targets t JOIN removal_batches b ON b.id=t.batch WHERE t.binding_id IS NOT NULL AND b.state=2;
CREATE TRIGGER compensated_parent BEFORE UPDATE OF state ON attempts WHEN NEW.state=4 AND NOT EXISTS(SELECT 1 FROM removal_batches WHERE compensates=NEW.id AND state=2) BEGIN SELECT RAISE(ABORT,'compensated parent requires a verified compensation'); END;
CREATE TABLE binding_records(id INTEGER PRIMARY KEY AUTOINCREMENT, audio BLOB NOT NULL CHECK(length(audio)=32), track BLOB NOT NULL UNIQUE CHECK(length(track)=8), path TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK(length(path) BETWEEN 1 AND 4096), first_attempt INTEGER UNIQUE REFERENCES attempts(id), provenance INTEGER NOT NULL CHECK(provenance IN(1,2,3)), UNIQUE(id,audio), CHECK((provenance=1)=(first_attempt IS NOT NULL))) STRICT;
CREATE TRIGGER immutable_binding_records_update BEFORE UPDATE ON binding_records BEGIN SELECT RAISE(ABORT,'journal history is immutable'); END;
CREATE TRIGGER immutable_binding_records_delete BEFORE DELETE ON binding_records BEGIN SELECT RAISE(ABORT,'journal history is immutable'); END;
CREATE TABLE binding_versions(binding_id INTEGER NOT NULL REFERENCES binding_records(id), version INTEGER NOT NULL CHECK(version BETWEEN 1 AND 4294967295), content BLOB NOT NULL CHECK(length(content)<=512), receipt BLOB NOT NULL CHECK(length(receipt)=32), anchor INTEGER NOT NULL CHECK(anchor BETWEEN 0 AND 4294967295), attempt INTEGER UNIQUE REFERENCES attempts(id), receipt_kind INTEGER NOT NULL CHECK(receipt_kind IN(1,2,3,4)), PRIMARY KEY(binding_id,version), CHECK(receipt_kind NOT IN(3,4) OR attempt IS NULL)) STRICT;
CREATE TRIGGER immutable_binding_versions_update BEFORE UPDATE ON binding_versions BEGIN SELECT RAISE(ABORT,'journal history is immutable'); END;
CREATE TRIGGER immutable_binding_versions_delete BEFORE DELETE ON binding_versions BEGIN SELECT RAISE(ABORT,'journal history is immutable'); END;
CREATE TRIGGER next_binding_version BEFORE INSERT ON binding_versions WHEN NEW.version!=COALESCE((SELECT MAX(version)+1 FROM binding_versions WHERE binding_id=NEW.binding_id),1) BEGIN SELECT RAISE(ABORT,'binding version is not next'); END;
CREATE TABLE binding_sources(binding_id INTEGER PRIMARY KEY REFERENCES binding_records(id), source TEXT NOT NULL CHECK(length(source) BETWEEN 2 AND 4096 AND substr(source,1,1)='/')) STRICT;
CREATE TRIGGER binding_source_immutable BEFORE UPDATE ON binding_sources BEGIN SELECT RAISE(ABORT,'journal history is immutable'); END;
CREATE TRIGGER binding_source_retained BEFORE DELETE ON binding_sources BEGIN SELECT RAISE(ABORT,'journal history is immutable'); END;
CREATE TABLE binding_conversions(binding_id INTEGER PRIMARY KEY REFERENCES binding_records(id), source_path TEXT NOT NULL CHECK(length(source_path) BETWEEN 2 AND 4096 AND substr(source_path,1,1)='/'), source_bytes INTEGER NOT NULL CHECK(source_bytes BETWEEN 1 AND 536870912), source_sha BLOB NOT NULL CHECK(length(source_sha)=32), source_audio BLOB NOT NULL CHECK(length(source_audio)=32), ffmpeg TEXT NOT NULL CHECK(length(ffmpeg) BETWEEN 1 AND 256)) STRICT;
CREATE INDEX binding_conversions_audio ON binding_conversions(source_audio);
CREATE TRIGGER binding_conversion_pulled BEFORE INSERT ON binding_conversions WHEN NOT EXISTS(SELECT 1 FROM binding_records WHERE id=NEW.binding_id AND provenance=3) BEGIN SELECT RAISE(ABORT,'a binding conversion belongs to a pulled binding'); END;
CREATE TRIGGER binding_conversion_immutable BEFORE UPDATE ON binding_conversions BEGIN SELECT RAISE(ABORT,'journal history is immutable'); END;
CREATE TRIGGER binding_conversion_retained BEFORE DELETE ON binding_conversions BEGIN SELECT RAISE(ABORT,'journal history is immutable'); END;
CREATE TABLE reservations(namespace INTEGER NOT NULL CHECK(namespace IN (1,2,3)), value BLOB NOT NULL, attempt INTEGER REFERENCES attempts(id), consumed INTEGER NOT NULL CHECK(consumed IN (0,1)), insert_batch INTEGER REFERENCES insert_batches(id), PRIMARY KEY(namespace,value), CHECK(attempt IS NULL OR insert_batch IS NULL)) STRICT;
CREATE TABLE coordination_steps(coordination INTEGER NOT NULL REFERENCES coordinations(id), step INTEGER NOT NULL CHECK(step>=0), batch INTEGER UNIQUE REFERENCES removal_batches(id), attempt INTEGER UNIQUE REFERENCES attempts(id), insert_batch INTEGER UNIQUE REFERENCES insert_batches(id), metadata_batch INTEGER UNIQUE REFERENCES metadata_batches(id), PRIMARY KEY(coordination,step), CHECK((batch IS NOT NULL)+(attempt IS NOT NULL)+(insert_batch IS NOT NULL)+(metadata_batch IS NOT NULL)=1)) STRICT;
CREATE TRIGGER coordination_step_next BEFORE INSERT ON coordination_steps WHEN NOT EXISTS(SELECT 1 FROM coordinations WHERE id=NEW.coordination AND state=0) OR NEW.step!=(SELECT count(*) FROM coordination_steps WHERE coordination=NEW.coordination) BEGIN SELECT RAISE(ABORT,'a coordination step extends an Active coordination in order'); END;
CREATE TRIGGER coordination_step_immutable BEFORE UPDATE ON coordination_steps BEGIN SELECT RAISE(ABORT,'coordination steps are immutable'); END;
CREATE TRIGGER coordination_step_retained BEFORE DELETE ON coordination_steps BEGIN SELECT RAISE(ABORT,'coordination history is retained'); END;
CREATE TABLE removal_batches(id INTEGER PRIMARY KEY AUTOINCREMENT, compensates INTEGER REFERENCES attempts(id), compensates_insert_batch INTEGER REFERENCES insert_batches(id), state INTEGER NOT NULL CHECK(state IN(0,1,2,3,4)), operation BLOB NOT NULL CHECK(length(operation) BETWEEN 1 AND 4194304), operation_sha BLOB NOT NULL CHECK(length(operation_sha)=32), base_anchor INTEGER NOT NULL CHECK(base_anchor BETWEEN 0 AND 4294967294), before_current BLOB NOT NULL CHECK(length(before_current)=32), before_index BLOB NOT NULL CHECK(length(before_index)=32), input_receipt BLOB NOT NULL CHECK(length(input_receipt)=32), evidence TEXT NOT NULL CHECK(length(evidence) BETWEEN 2 AND 4096 AND substr(evidence,1,1)='/'), ready_receipt BLOB CHECK(ready_receipt IS NULL OR length(ready_receipt)=32), signature BLOB CHECK(signature IS NULL OR length(signature)=21), result_receipt BLOB CHECK(result_receipt IS NULL OR length(result_receipt)=32), verified_anchor INTEGER CHECK(verified_anchor IS NULL OR verified_anchor BETWEEN 1 AND 4294967295), with_insert_batch INTEGER UNIQUE REFERENCES insert_batches(id), CHECK((state IN(0,3) AND ready_receipt IS NULL AND signature IS NULL AND result_receipt IS NULL AND verified_anchor IS NULL) OR (state=1 AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND result_receipt IS NULL AND verified_anchor IS NULL) OR (state=2 AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND result_receipt IS NOT NULL AND verified_anchor IS NOT NULL) OR (state=4 AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND result_receipt IS NOT NULL AND verified_anchor IS NULL)), CHECK((compensates IS NOT NULL)+(compensates_insert_batch IS NOT NULL)+(with_insert_batch IS NOT NULL)<=1)) STRICT;
CREATE UNIQUE INDEX one_outstanding_batch ON removal_batches((1)) WHERE state IN(0,1);
CREATE UNIQUE INDEX one_insert_compensation_batch ON removal_batches(compensates_insert_batch) WHERE compensates_insert_batch IS NOT NULL AND state IN(0,1,2);
CREATE TRIGGER removal_batch_prepared BEFORE INSERT ON removal_batches WHEN NEW.state!=0 OR EXISTS(SELECT 1 FROM attempts WHERE state IN(0,1) AND id IS NOT NEW.compensates) OR EXISTS(SELECT 1 FROM insert_batches WHERE state IN(0,1,5) AND id IS NOT NEW.compensates_insert_batch AND id IS NOT NEW.with_insert_batch) OR EXISTS(SELECT 1 FROM metadata_batches WHERE state IN(0,1)) BEGIN SELECT RAISE(ABORT,'a removal batch is Prepared on an idle journal'); END;
CREATE TRIGGER removal_batch_compensates BEFORE INSERT ON removal_batches WHEN NEW.compensates IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM attempts WHERE id=NEW.compensates AND kind=1 AND state=1)) BEGIN SELECT RAISE(ABORT,'a compensating batch requires a Started Insert'); END;
CREATE TRIGGER removal_batch_compensates_insert BEFORE INSERT ON removal_batches WHEN NEW.compensates_insert_batch IS NOT NULL AND NOT EXISTS(SELECT 1 FROM insert_batches WHERE id=NEW.compensates_insert_batch AND state=5) BEGIN SELECT RAISE(ABORT,'a compensating batch requires a Partial insert batch'); END;
CREATE TRIGGER removal_batch_session BEFORE INSERT ON removal_batches WHEN NEW.with_insert_batch IS NOT NULL AND NOT EXISTS(SELECT 1 FROM insert_batches WHERE id=NEW.with_insert_batch AND state=0 AND coordination IS NULL AND operation_sha=NEW.operation_sha AND base_anchor=NEW.base_anchor AND before_current=NEW.before_current AND before_index=NEW.before_index AND input_receipt=NEW.input_receipt AND evidence=NEW.evidence) BEGIN SELECT RAISE(ABORT,'a session''s removal half pairs with its Prepared insert half, sharing its operation and evidence'); END;
CREATE TRIGGER removal_batch_session_start BEFORE UPDATE OF state ON removal_batches WHEN NEW.state=1 AND NEW.with_insert_batch IS NOT NULL AND NOT EXISTS(SELECT 1 FROM insert_batches WHERE id=NEW.with_insert_batch AND state=1 AND ready_receipt=NEW.ready_receipt AND signature=NEW.signature) BEGIN SELECT RAISE(ABORT,'a session''s removal half starts with its insert half'); END;
CREATE TRIGGER removal_batch_immutable BEFORE UPDATE OF id,compensates,compensates_insert_batch,with_insert_batch,operation,operation_sha,base_anchor,before_current,before_index,input_receipt,evidence ON removal_batches BEGIN SELECT RAISE(ABORT,'removal batch preparation is immutable'); END;
CREATE TRIGGER removal_batch_start_immutable BEFORE UPDATE OF ready_receipt,signature ON removal_batches WHEN OLD.state!=0 BEGIN SELECT RAISE(ABORT,'removal batch start is immutable'); END;
CREATE TRIGGER removal_batch_forward BEFORE UPDATE OF state ON removal_batches WHEN NOT ((OLD.state=0 AND NEW.state IN(1,3)) OR (OLD.state=1 AND NEW.state IN(2,4))) BEGIN SELECT RAISE(ABORT,'invalid removal batch transition'); END;
CREATE TRIGGER removal_batch_terminal BEFORE UPDATE ON removal_batches WHEN OLD.state IN(2,3,4) BEGIN SELECT RAISE(ABORT,'removal batch outcome is immutable'); END;
CREATE TRIGGER removal_batch_retained BEFORE DELETE ON removal_batches BEGIN SELECT RAISE(ABORT,'removal batch history is retained'); END;
CREATE TRIGGER removal_batch_compensation_complete BEFORE UPDATE OF state ON removal_batches WHEN NEW.state=1 AND NEW.compensates_insert_batch IS NOT NULL AND (SELECT count(*) FROM removal_targets WHERE batch=NEW.id)!=(SELECT count(*) FROM insert_targets WHERE batch=NEW.compensates_insert_batch AND outcome=2) BEGIN SELECT RAISE(ABORT,'a compensating batch removes exactly the locationless rows of its insert batch'); END;
CREATE TRIGGER removal_target_insert_compensation BEFORE INSERT ON removal_targets WHEN EXISTS(SELECT 1 FROM removal_batches WHERE id=NEW.batch AND compensates_insert_batch IS NOT NULL) AND (NEW.path IS NOT NULL OR NEW.binding_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM insert_targets t JOIN removal_batches b ON b.compensates_insert_batch=t.batch WHERE b.id=NEW.batch AND t.track=NEW.track AND t.outcome=2)) BEGIN SELECT RAISE(ABORT,'a compensating batch removes only locationless unowned rows of its insert batch'); END;
CREATE TABLE insert_batches(id INTEGER PRIMARY KEY AUTOINCREMENT, coordination INTEGER REFERENCES coordinations(id), state INTEGER NOT NULL CHECK(state IN(0,1,2,3,4,5,6)), operation BLOB NOT NULL CHECK(length(operation) BETWEEN 1 AND 4194304), operation_sha BLOB NOT NULL CHECK(length(operation_sha)=32), base_anchor INTEGER NOT NULL CHECK(base_anchor BETWEEN 0 AND 4294967294), before_current BLOB NOT NULL CHECK(length(before_current)=32), before_index BLOB NOT NULL CHECK(length(before_index)=32), input_receipt BLOB NOT NULL CHECK(length(input_receipt)=32), evidence TEXT NOT NULL CHECK(length(evidence) BETWEEN 2 AND 4096 AND substr(evidence,1,1)='/'), ready_receipt BLOB CHECK(ready_receipt IS NULL OR length(ready_receipt)=32), signature BLOB CHECK(signature IS NULL OR length(signature)=21), result_receipt BLOB CHECK(result_receipt IS NULL OR length(result_receipt)=32), verified_anchor INTEGER CHECK(verified_anchor IS NULL OR verified_anchor BETWEEN 1 AND 4294967295), CHECK((state IN(0,3) AND ready_receipt IS NULL AND signature IS NULL AND result_receipt IS NULL AND verified_anchor IS NULL) OR (state=1 AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND result_receipt IS NULL AND verified_anchor IS NULL) OR (state IN(2,5,6) AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND result_receipt IS NOT NULL AND verified_anchor IS NOT NULL) OR (state=4 AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND result_receipt IS NOT NULL AND verified_anchor IS NULL))) STRICT;
CREATE UNIQUE INDEX one_outstanding_insert_batch ON insert_batches((1)) WHERE state IN(0,1,5);
CREATE TRIGGER insert_batch_prepared BEFORE INSERT ON insert_batches WHEN NEW.state!=0 OR EXISTS(SELECT 1 FROM attempts WHERE state IN(0,1)) OR EXISTS(SELECT 1 FROM removal_batches WHERE state IN(0,1)) OR EXISTS(SELECT 1 FROM metadata_batches WHERE state IN(0,1)) OR EXISTS(SELECT 1 FROM insert_batches WHERE state IN(0,1,5)) BEGIN SELECT RAISE(ABORT,'an insert batch is Prepared on an idle journal'); END;
CREATE TRIGGER insert_batch_coordination BEFORE INSERT ON insert_batches WHEN NEW.coordination IS NOT NULL AND NOT EXISTS(SELECT 1 FROM coordinations WHERE id=NEW.coordination AND state=0) BEGIN SELECT RAISE(ABORT,'an insert batch names an Active coordination'); END;
CREATE TRIGGER insert_batch_immutable BEFORE UPDATE OF id,coordination,operation,operation_sha,base_anchor,before_current,before_index,input_receipt,evidence ON insert_batches BEGIN SELECT RAISE(ABORT,'insert batch preparation is immutable'); END;
CREATE TRIGGER insert_batch_start_immutable BEFORE UPDATE OF ready_receipt,signature ON insert_batches WHEN OLD.state!=0 BEGIN SELECT RAISE(ABORT,'insert batch start is immutable'); END;
CREATE TRIGGER insert_batch_result_immutable BEFORE UPDATE OF result_receipt,verified_anchor ON insert_batches WHEN OLD.state NOT IN(0,1) BEGIN SELECT RAISE(ABORT,'insert batch result is immutable'); END;
CREATE TRIGGER insert_batch_terminal BEFORE UPDATE ON insert_batches WHEN OLD.state IN(2,3,4,6) BEGIN SELECT RAISE(ABORT,'insert batch outcome is immutable'); END;
CREATE TRIGGER insert_batch_retained BEFORE DELETE ON insert_batches BEGIN SELECT RAISE(ABORT,'insert batch history is retained'); END;
CREATE TRIGGER attempt_insert_batch_outstanding BEFORE INSERT ON attempts WHEN EXISTS(SELECT 1 FROM insert_batches WHERE state IN(0,1,5)) BEGIN SELECT RAISE(ABORT,'an outstanding insert batch requires settlement'); END;
CREATE TABLE metadata_batches(id INTEGER PRIMARY KEY AUTOINCREMENT, coordination INTEGER REFERENCES coordinations(id), state INTEGER NOT NULL CHECK(state IN(0,1,2,3,4)), operation BLOB NOT NULL CHECK(length(operation) BETWEEN 1 AND 4194304), operation_sha BLOB NOT NULL CHECK(length(operation_sha)=32), base_anchor INTEGER NOT NULL CHECK(base_anchor BETWEEN 0 AND 4294967294), before_current BLOB NOT NULL CHECK(length(before_current)=32), before_index BLOB NOT NULL CHECK(length(before_index)=32), input_receipt BLOB NOT NULL CHECK(length(input_receipt)=32), evidence TEXT NOT NULL CHECK(length(evidence) BETWEEN 2 AND 4096 AND substr(evidence,1,1)='/'), ready_receipt BLOB CHECK(ready_receipt IS NULL OR length(ready_receipt)=32), signature BLOB CHECK(signature IS NULL OR length(signature)=21), result_receipt BLOB CHECK(result_receipt IS NULL OR length(result_receipt)=32), verified_anchor INTEGER CHECK(verified_anchor IS NULL OR verified_anchor BETWEEN 1 AND 4294967295), CHECK((state IN(0,3) AND ready_receipt IS NULL AND signature IS NULL AND result_receipt IS NULL AND verified_anchor IS NULL) OR (state=1 AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND result_receipt IS NULL AND verified_anchor IS NULL) OR (state=2 AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND result_receipt IS NOT NULL AND verified_anchor IS NOT NULL) OR (state=4 AND ready_receipt IS NOT NULL AND signature IS NOT NULL AND result_receipt IS NOT NULL AND verified_anchor IS NULL))) STRICT;
CREATE UNIQUE INDEX one_outstanding_metadata_batch ON metadata_batches((1)) WHERE state IN(0,1);
CREATE TRIGGER metadata_batch_prepared BEFORE INSERT ON metadata_batches WHEN NEW.state!=0 OR EXISTS(SELECT 1 FROM attempts WHERE state IN(0,1)) OR EXISTS(SELECT 1 FROM removal_batches WHERE state IN(0,1)) OR EXISTS(SELECT 1 FROM insert_batches WHERE state IN(0,1,5)) OR EXISTS(SELECT 1 FROM metadata_batches WHERE state IN(0,1)) BEGIN SELECT RAISE(ABORT,'a metadata batch is Prepared on an idle journal'); END;
CREATE TRIGGER metadata_batch_coordination BEFORE INSERT ON metadata_batches WHEN NEW.coordination IS NOT NULL AND NOT EXISTS(SELECT 1 FROM coordinations WHERE id=NEW.coordination AND state=0) BEGIN SELECT RAISE(ABORT,'a metadata batch names an Active coordination'); END;
CREATE TRIGGER metadata_batch_immutable BEFORE UPDATE OF id,coordination,operation,operation_sha,base_anchor,before_current,before_index,input_receipt,evidence ON metadata_batches BEGIN SELECT RAISE(ABORT,'metadata batch preparation is immutable'); END;
CREATE TRIGGER metadata_batch_start_immutable BEFORE UPDATE OF ready_receipt,signature ON metadata_batches WHEN OLD.state!=0 BEGIN SELECT RAISE(ABORT,'metadata batch start is immutable'); END;
CREATE TRIGGER metadata_batch_forward BEFORE UPDATE OF state ON metadata_batches WHEN NOT ((OLD.state=0 AND NEW.state IN(1,3)) OR (OLD.state=1 AND NEW.state IN(2,4))) BEGIN SELECT RAISE(ABORT,'invalid metadata batch transition'); END;
CREATE TRIGGER metadata_batch_terminal BEFORE UPDATE ON metadata_batches WHEN OLD.state IN(2,3,4) BEGIN SELECT RAISE(ABORT,'metadata batch outcome is immutable'); END;
CREATE TRIGGER metadata_batch_retained BEFORE DELETE ON metadata_batches BEGIN SELECT RAISE(ABORT,'metadata batch history is retained'); END;
CREATE TRIGGER attempt_metadata_batch_outstanding BEFORE INSERT ON attempts WHEN EXISTS(SELECT 1 FROM metadata_batches WHERE state IN(0,1)) BEGIN SELECT RAISE(ABORT,'an outstanding metadata batch requires settlement'); END;
CREATE TABLE metadata_targets(batch INTEGER NOT NULL REFERENCES metadata_batches(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), track BLOB NOT NULL CHECK(length(track)=8), PRIMARY KEY(batch,ordinal), UNIQUE(batch,track)) STRICT;
CREATE TRIGGER metadata_target_next BEFORE INSERT ON metadata_targets WHEN NOT EXISTS(SELECT 1 FROM metadata_batches WHERE id=NEW.batch AND state=0) OR NEW.ordinal!=(SELECT count(*) FROM metadata_targets WHERE batch=NEW.batch) BEGIN SELECT RAISE(ABORT,'a metadata target extends a Prepared batch in order'); END;
CREATE TRIGGER metadata_target_immutable BEFORE UPDATE ON metadata_targets BEGIN SELECT RAISE(ABORT,'metadata targets are immutable'); END;
CREATE TRIGGER metadata_target_retained BEFORE DELETE ON metadata_targets BEGIN SELECT RAISE(ABORT,'metadata target history is retained'); END;
CREATE TABLE insert_targets(batch INTEGER NOT NULL REFERENCES insert_batches(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), track BLOB NOT NULL UNIQUE CHECK(length(track)=8), path TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK(length(path) BETWEEN 1 AND 4096), content BLOB NOT NULL CHECK(length(content)<=512), new_album BLOB CHECK(new_album IS NULL OR length(new_album)=8), new_artist BLOB CHECK(new_artist IS NULL OR length(new_artist)=8), outcome INTEGER CHECK(outcome IS NULL OR outcome IN(1,2,3,4)), binding_id INTEGER, binding_version INTEGER, PRIMARY KEY(batch,ordinal), UNIQUE(batch,track), FOREIGN KEY(binding_id,binding_version) REFERENCES binding_versions(binding_id,version), CHECK((binding_id IS NULL)=(binding_version IS NULL)), CHECK((outcome IS 1)=(binding_id IS NOT NULL))) STRICT;
CREATE TRIGGER insert_target_next BEFORE INSERT ON insert_targets WHEN NOT EXISTS(SELECT 1 FROM insert_batches WHERE id=NEW.batch AND state=0) OR NEW.ordinal!=(SELECT count(*) FROM insert_targets WHERE batch=NEW.batch) OR NEW.outcome IS NOT NULL OR NEW.binding_id IS NOT NULL BEGIN SELECT RAISE(ABORT,'an insert target extends a Prepared batch in order'); END;
CREATE TRIGGER insert_target_immutable BEFORE UPDATE OF batch,ordinal,track,path,content,new_album,new_artist ON insert_targets BEGIN SELECT RAISE(ABORT,'insert target preparation is immutable'); END;
CREATE TRIGGER insert_target_outcome BEFORE UPDATE OF outcome,binding_id,binding_version ON insert_targets WHEN NOT ((OLD.outcome IS NULL AND NEW.outcome IS NOT NULL AND NEW.outcome IN(1,2,4) AND EXISTS(SELECT 1 FROM insert_batches WHERE id=OLD.batch AND state=1)) OR (OLD.outcome IS 2 AND NEW.outcome IS 3 AND EXISTS(SELECT 1 FROM insert_batches WHERE id=OLD.batch AND state=5) AND EXISTS(SELECT 1 FROM removal_batches WHERE compensates_insert_batch=OLD.batch AND state=2))) BEGIN SELECT RAISE(ABORT,'invalid insert target outcome'); END;
CREATE TRIGGER insert_target_binding BEFORE UPDATE OF outcome,binding_id,binding_version ON insert_targets WHEN NEW.outcome IS 1 AND NOT EXISTS(SELECT 1 FROM binding_records r WHERE r.id=NEW.binding_id AND r.track=NEW.track AND r.path=NEW.path AND r.provenance=2) BEGIN SELECT RAISE(ABORT,'a bound insert target names the binding of its own track'); END;
CREATE TRIGGER insert_target_retained BEFORE DELETE ON insert_targets BEGIN SELECT RAISE(ABORT,'insert target history is retained'); END;
CREATE TRIGGER insert_batch_forward BEFORE UPDATE OF state ON insert_batches WHEN NOT ((OLD.state=0 AND NEW.state IN(1,3)) OR (OLD.state=1 AND NEW.state IN(2,4,5,6)) OR (OLD.state=5 AND NEW.state=6)) BEGIN SELECT RAISE(ABORT,'invalid insert batch transition'); END;
CREATE TRIGGER insert_batch_session_state BEFORE UPDATE OF state ON insert_batches WHEN EXISTS(SELECT 1 FROM removal_batches WHERE with_insert_batch=NEW.id AND state!=CASE NEW.state WHEN 1 THEN 0 WHEN 3 THEN 3 WHEN 4 THEN 4 ELSE 2 END) BEGIN SELECT RAISE(ABORT,'a session''s insert half changes state after its removal half'); END;
CREATE TRIGGER insert_batch_outcomes BEFORE UPDATE OF state ON insert_batches WHEN (NEW.state=2 AND EXISTS(SELECT 1 FROM insert_targets WHERE batch=NEW.id AND outcome IS NOT 1)) OR (NEW.state=5 AND (EXISTS(SELECT 1 FROM insert_targets WHERE batch=NEW.id AND outcome IS NULL) OR NOT EXISTS(SELECT 1 FROM insert_targets WHERE batch=NEW.id AND outcome=2))) OR (NEW.state=6 AND (EXISTS(SELECT 1 FROM insert_targets WHERE batch=NEW.id AND (outcome IS NULL OR outcome NOT IN(1,3,4))) OR NOT EXISTS(SELECT 1 FROM insert_targets WHERE batch=NEW.id AND outcome IN(3,4)) OR (EXISTS(SELECT 1 FROM insert_targets WHERE batch=NEW.id AND outcome=3) AND NOT EXISTS(SELECT 1 FROM removal_batches WHERE compensates_insert_batch=NEW.id AND state=2)))) OR (NEW.state IN(3,4) AND EXISTS(SELECT 1 FROM insert_targets WHERE batch=NEW.id AND outcome IS NOT NULL)) BEGIN SELECT RAISE(ABORT,'insert batch state differs from its target outcomes'); END;
CREATE TABLE removal_playlists(batch INTEGER NOT NULL REFERENCES removal_batches(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), container BLOB NOT NULL CHECK(length(container)=8 AND container!=zeroblob(8)), name TEXT NOT NULL CHECK(length(name)<=4096), PRIMARY KEY(batch,ordinal), UNIQUE(batch,container)) STRICT;
CREATE TRIGGER removal_playlist_next BEFORE INSERT ON removal_playlists WHEN NOT EXISTS(SELECT 1 FROM removal_batches WHERE id=NEW.batch AND state=0 AND compensates IS NULL AND compensates_insert_batch IS NULL AND with_insert_batch IS NULL) OR NEW.ordinal!=(SELECT count(*) FROM removal_playlists WHERE batch=NEW.batch) OR EXISTS(SELECT 1 FROM removal_targets WHERE batch=NEW.batch) BEGIN SELECT RAISE(ABORT,'a removal playlist extends a Prepared playlist batch in order'); END;
CREATE TRIGGER removal_playlist_immutable BEFORE UPDATE ON removal_playlists BEGIN SELECT RAISE(ABORT,'removal playlist history is immutable'); END;
CREATE TRIGGER removal_playlist_retained BEFORE DELETE ON removal_playlists BEGIN SELECT RAISE(ABORT,'removal playlist history is retained'); END;
CREATE TRIGGER removal_target_not_playlist BEFORE INSERT ON removal_targets WHEN EXISTS(SELECT 1 FROM removal_playlists WHERE batch=NEW.batch) BEGIN SELECT RAISE(ABORT,'a removal batch removes tracks or playlists, not both'); END;
CREATE TRIGGER removal_batch_has_rows BEFORE UPDATE OF state ON removal_batches WHEN NEW.state=1 AND NOT EXISTS(SELECT 1 FROM removal_targets WHERE batch=NEW.id) AND NOT EXISTS(SELECT 1 FROM removal_playlists WHERE batch=NEW.id) BEGIN SELECT RAISE(ABORT,'a removal batch starts with rows to remove'); END;
CREATE TABLE insert_conversions(batch INTEGER NOT NULL, ordinal INTEGER NOT NULL, source_path TEXT NOT NULL CHECK(length(source_path) BETWEEN 2 AND 4096 AND substr(source_path,1,1)='/'), source_bytes INTEGER NOT NULL CHECK(source_bytes BETWEEN 1 AND 536870912), source_sha BLOB NOT NULL CHECK(length(source_sha)=32), source_audio BLOB NOT NULL CHECK(length(source_audio)=32), ffmpeg TEXT NOT NULL CHECK(length(ffmpeg) BETWEEN 1 AND 256), PRIMARY KEY(batch,ordinal), FOREIGN KEY(batch,ordinal) REFERENCES insert_targets(batch,ordinal)) STRICT;
CREATE INDEX insert_conversions_audio ON insert_conversions(source_audio);
CREATE TRIGGER insert_conversion_prepared BEFORE INSERT ON insert_conversions WHEN NOT EXISTS(SELECT 1 FROM insert_targets t JOIN insert_batches b ON b.id=t.batch WHERE t.batch=NEW.batch AND t.ordinal=NEW.ordinal AND b.state=0) BEGIN SELECT RAISE(ABORT,'a conversion is recorded with its Prepared insert target'); END;
CREATE TRIGGER insert_conversion_immutable BEFORE UPDATE ON insert_conversions BEGIN SELECT RAISE(ABORT,'journal history is immutable'); END;
CREATE TRIGGER insert_conversion_retained BEFORE DELETE ON insert_conversions BEGIN SELECT RAISE(ABORT,'journal history is immutable'); END;
CREATE TABLE insert_sources(batch INTEGER NOT NULL, ordinal INTEGER NOT NULL, source TEXT NOT NULL CHECK(length(source) BETWEEN 2 AND 4096 AND substr(source,1,1)='/'), PRIMARY KEY(batch,ordinal), FOREIGN KEY(batch,ordinal) REFERENCES insert_targets(batch,ordinal)) STRICT;
CREATE TRIGGER insert_source_prepared BEFORE INSERT ON insert_sources WHEN NOT EXISTS(SELECT 1 FROM insert_targets t JOIN insert_batches b ON b.id=t.batch WHERE t.batch=NEW.batch AND t.ordinal=NEW.ordinal AND b.state=0) BEGIN SELECT RAISE(ABORT,'a source is recorded with its Prepared insert target'); END;
CREATE TRIGGER insert_source_immutable BEFORE UPDATE ON insert_sources BEGIN SELECT RAISE(ABORT,'journal history is immutable'); END;
CREATE TRIGGER insert_source_retained BEFORE DELETE ON insert_sources BEGIN SELECT RAISE(ABORT,'journal history is immutable'); END;
